package ai.magpie.android;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
/** Disposable SDK emulator: constrained-width reachability, not a vendor account test. */
public final class NativeResponsiveAcceptance extends Instrumentation {
 private Activity home;private String mode;private File evidence;
 private static final String PROVIDER="很长的服务商名称 / production-workspace-API";
 @Override public void onCreate(Bundle args){super.onCreate(args);mode=args.getString("mode","flow");start();}
 @Override public void onStart(){try{Context c=getTargetContext();c.getSharedPreferences("host",0).edit().putBoolean("launched",true).putBoolean("askedNotifications",true).putBoolean("remote",false).commit();evidence=new File(c.getFilesDir(),"responsive-acceptance");evidence.mkdirs();home=startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
  if(mode.equals("functions")||mode.equals("flow")){capture("01-tools-entry");require(find(home.getWindow().getDecorView(),"工具")!=null,"Permanent tools destination missing");Activity models=home;home=startActivitySync(new Intent(c,ToolsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{try{((EditText)get(home,"search")).setText("");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->find(home.getWindow().getDecorView(),"打开资料库")!=null,"Library entry unavailable");reveal(home.getWindow().getDecorView(),"打开资料库");capture("02-tools-directory");reveal(home.getWindow().getDecorView(),"打开关于与开源许可");capture("02-tools-bottom");ui(home::finish);home=models;if(!mode.equals("flow")){pass();return;}}
  if(mode.equals("packing")||mode.equals("flow")){ui(()->{try{GatewayService.ready=true;JSONArray models=new JSONArray();for(int i=0;i<5000;i++)models.put(new JSONObject().put("id","m"+i).put("on",true));WorkspaceSnapshot s=WorkspaceSnapshot.parse(new JSONObject().put("providers",new JSONArray().put(new JSONObject().put("id","responsive").put("name",PROVIDER).put("models",models))).put("gateway",new JSONObject().put("url","http://127.0.0.1:18789")).toString(),"{\"groups\":[]}");set(home,"catalog",s);invoke(home,"renderCatalog");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->find(home.getWindow().getDecorView(),PROVIDER)!=null,"Provider not rendered");View name=find(home.getWindow().getDecorView(),PROVIDER);waitFor(()->name.getWidth()>0,"Provider layout pending");ui(()->name.requestRectangleOnScreen(new Rect(0,0,name.getWidth(),name.getHeight()),true));capture("03-provider-width");require(name.getWidth()>=getTargetContext().getResources().getDisplayMetrics().widthPixels*.6,"Provider name squeezed into a narrow column");if(!mode.equals("flow")){pass();return;}}
  if(mode.equals("actions")||mode.equals("fixed")||mode.equals("resize")||mode.equals("flow")){
   AtomicReference<Dialog> ref=new AtomicReference<>();ui(()->ref.set(ConnectionSheet.show(home,new Ui(home),"http://127.0.0.1:18789","responsive/long-model-identifier-2026",()->{},false,()->true)));Dialog d=ref.get();View root=d.getWindow().getDecorView();waitFor(()->find(root,"复制接入信息").getWidth()>0,"Action layout pending");if(mode.equals("fixed"))visible(root,"复制接入信息");checkSheet(root);capture("04-action-wrap");
   if(mode.equals("resize"))for(int width:new int[]{560,280,560}){ui(()->d.getWindow().setLayout(width,320));waitFor(()->root.getWidth()==width,"Open sheet width did not update");checkSheet(root);capture("04-resize-"+width);}
   ui(d::dismiss);if(!mode.equals("flow")){pass();return;}
  }
  if(mode.equals("error")||mode.equals("flow")){
   ui(()->GatewayService.ready=false);home=startActivitySync(new Intent(c,ManagementActivity.class).putExtra("view","library").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
   ui(()->{try{Method m=home.getClass().getDeclaredMethod("showError",String.class,String.class);m.setAccessible(true);m.invoke(home,"连接失败","错误恢复说明。".repeat(40));}catch(Exception e){throw new RuntimeException(e);}});
   View recovery=(View)get(home,"error");View back=find(recovery,"返回工具");waitFor(()->back.getHeight()>0,"Error actions not laid out");ui(()->back.requestRectangleOnScreen(new Rect(0,0,back.getWidth(),back.getHeight()),true));visible(recovery,"返回工具");visible(home.getWindow().getDecorView(),"工具");capture("05-error-recovery");
  }
  Bundle ok=new Bundle();ok.putString("stream","PASS visible functions, reachable menu entries, full-width provider name, unsqueezed connection actions and scrollable error recovery");finish(Activity.RESULT_OK,ok);
 }catch(Throwable e){Bundle out=new Bundle();out.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
 private void pass(){Bundle ok=new Bundle();ok.putString("stream","PASS responsive scenario");finish(Activity.RESULT_OK,ok);}
 private void checkSheet(View root)throws Exception{
  TextView copy=(TextView)find(root,"复制接入信息");require(copy.getPaint().measureText(copy.getText().toString())<=copy.getWidth()-copy.getPaddingLeft()-copy.getPaddingRight()+1,"Copy action squeezed into multiple lines");
  for(String text:new String[]{"复制接入信息","测试当前接口","复制接入模型标识","复制 Base URL","复制 API Key","复制 OpenAI JSON 配置","网关与访问密钥 →"})reveal(root,text);
  String pin=find(root,"收藏模型")!=null?"收藏模型":"取消收藏";reveal(root,pin);click(root,pin);require(find(root,"取消收藏")!=null,"Favorite did not respond");reveal(root,"复制接入信息");
 }
 private void reveal(View root,String text)throws Exception{View v=find(root,text);require(v!=null,"Missing sheet action: "+text);ui(()->v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true));visible(root,text);}
 private interface Check{boolean get()throws Exception;}private void waitFor(Check c,String why)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){AtomicReference<Boolean> v=new AtomicReference<>(false);ui(()->{try{v.set(c.get());}catch(Exception e){throw new RuntimeException(e);}});if(v.get())return;Thread.sleep(100);}throw new AssertionError(why);}
 private void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable x){e.set(x);}});if(e.get()!=null)throw new AssertionError(e.get());}
 private static Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}private static void set(Object o,String n,Object v){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}catch(Exception e){throw new RuntimeException(e);}}
 private static void invoke(Object o,String n){try{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}catch(Exception e){throw new RuntimeException(e);}}
 private static View find(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||(v instanceof TextView&&label.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),label);if(f!=null)return f;}return null;}
 private void click(View r,String label)throws Exception{waitFor(()->find(r,label)!=null,"Missing "+label);ui(()->{View v=find(r,label);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.performClick();});}
 private void visible(View r,String label)throws Exception{waitFor(()->{View v=find(r,label);Rect b=new Rect();return v!=null&&v.getGlobalVisibleRect(b)&&b.height()>=v.getHeight()-1&&b.height()>=44*getTargetContext().getResources().getDisplayMetrics().density;},"Action is offscreen: "+label);}
 private static void require(boolean b,String why){if(!b)throw new AssertionError(why);}private void capture(String n)throws Exception{getUiAutomation().waitForIdle(250,10000);Thread.sleep(1500);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(evidence,n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
